package com.diberlog.jarvis.mobile;

import org.json.*;
import org.xmlpull.v1.XmlPullParser;
import android.util.Xml;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

final class PublicData {
    static String read(InputStream input,int limit)throws Exception{if(input==null)throw new IOException("Источник не ответил");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Ответ источника слишком большой");out.write(b,0,n);}return out.toString("UTF-8");}}
    static URL redirect(URL from,String location)throws Exception{if(location==null||location.length()>2048)throw new IOException("Источник не указал адрес перенаправления");URL next=new URL(from,location);validateUrl(next);return next;}
    static void validateUrl(URL url)throws IOException{if(!"https".equals(url.getProtocol())||url.getUserInfo()!=null||url.getHost().isEmpty()||url.getPort()!=-1&&url.getPort()!=443)throw new IOException("Нужна публичная HTTPS-ссылка без логина и пароля");String host=url.getHost().toLowerCase(java.util.Locale.ROOT);if(host.equals("localhost")||host.endsWith(".localhost")||host.endsWith(".local"))throw new IOException("Внутренние адреса не поддерживаются для новостей");}
    static boolean publicAddress(InetAddress ip){byte[] b=ip.getAddress();return !ip.isAnyLocalAddress()&&!ip.isLoopbackAddress()&&!ip.isLinkLocalAddress()&&!ip.isSiteLocalAddress()&&!ip.isMulticastAddress()&&!(b.length==16&&(b[0]&0xfe)==0xfc);}
    static String get(String address)throws Exception{URL url=new URL(address);java.util.Set<String> seen=new java.util.HashSet<>();for(int hop=0;hop<=4;hop++){validateUrl(url);if(!seen.add(url.toString()))throw new IOException("Источник зациклил перенаправления");try{for(InetAddress ip:InetAddress.getAllByName(url.getHost()))if(!publicAddress(ip))throw new IOException("Источник указывает на внутреннюю сеть");}catch(UnknownHostException e){throw new IOException("Не удалось найти источник. Проверьте интернет и DNS");}HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(8000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","JARVIS-Mobile/1.1.5");c.setRequestProperty("Accept","application/rss+xml, application/atom+xml, application/json, application/xml, text/xml, */*");try{int status=c.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){url=redirect(url,c.getHeaderField("Location"));continue;}if(status!=200)throw new IOException("Источник вернул HTTP "+status+". Попробуйте другую ленту");return read(c.getInputStream(),2*1024*1024);}catch(SocketTimeoutException e){throw new IOException("Источник не ответил вовремя. Сохранённые данные остаются на устройстве");}catch(UnknownHostException e){throw new IOException("Не удалось найти источник. Проверьте интернет и DNS");}finally{c.disconnect();}}throw new IOException("Слишком много перенаправлений источника");}

    static String plain(String html,int limit){String text=android.text.Html.fromHtml(html,android.text.Html.FROM_HTML_MODE_LEGACY).toString().replace("\uFFFC","").replaceAll("\\s+"," ").trim();return text.substring(0,Math.min(limit,text.length()));}
    static String news(String url)throws Exception{return parseNews(get(url),new URL(url).getHost()).toString();}
    static JSONArray parseNews(String xml,String fallback)throws Exception{String upper=xml.toUpperCase(java.util.Locale.ROOT);if(upper.contains("<!DOCTYPE")||upper.contains("<!ENTITY"))throw new IOException("Небезопасный формат RSS: DTD не поддерживается");XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,false);p.setInput(new StringReader(xml));JSONArray items=new JSONArray();String title="",link="",summary="",published="",source=fallback,categories="";boolean inside=false;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){
        if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("item")||tag.equals("entry")){inside=true;title="";link="";summary="";published="";source=fallback;categories="";}
        else if(inside&&tag.equals("category"))categories+=" "+p.nextText();else if(inside&&tag.equals("title"))title=p.nextText();else if(inside&&tag.equals("link")){String href=p.getAttributeValue(null,"href");link=href==null?p.nextText():href;}
        else if(inside&&(tag.equals("description")||tag.equals("summary")))summary=p.nextText();else if(inside&&(tag.equals("pubDate")||tag.equals("published")||tag.equals("updated")))published=p.nextText();else if(inside&&tag.equals("source"))source=p.nextText();}
        else if(event==XmlPullParser.END_TAG&&(p.getName().equals("item")||p.getName().equals("entry"))){inside=false;try{URL target=new URL(link);if((target.getProtocol().equals("https")||target.getProtocol().equals("http"))&&target.getUserInfo()==null&&!title.trim().isEmpty())items.put(new JSONObject().put("title",plain(title,1000)).put("url",link).put("summary",plain(summary,2000)).put("published_at",published).put("source",plain(source,150)).put("categories",plain(categories,500)));}catch(MalformedURLException ignored){}if(items.length()>=30)break;}}
        if(items.length()==0)throw new IOException("В RSS не найдены новости с ссылками. Попробуйте другой источник");return items;}
    static String newsFeed(String topic,String region,String domain){
        if(domain.equals("interfax.ru"))return "https://www.interfax.ru/rss";
        if(domain.equals("rbc.ru"))return "https://rssexport.rbc.ru/rbcnews/news/30/full.rss";
        if(domain.equals("theverge.com"))return "https://www.theverge.com/rss/index.xml";
        if(domain.equals("bbc.com")||domain.isEmpty()&&!region.equals("ru")){String section=topic.equals("sport")?"sport":topic.equals("economy")?"news/business":topic.equals("science")||topic.equals("space")?"news/science_and_environment":topic.equals("all")?"news":"news/technology";return "https://feeds.bbci.co.uk/"+section+"/rss.xml";}
        if(domain.equals("lenta.ru"))return "https://lenta.ru/rss/news"+(topic.equals("sport")?"/sport/":topic.equals("economy")?"/economics/":topic.equals("science")||topic.equals("tech")||topic.equals("space")||topic.equals("ai")?"/science/":"");
        if(domain.equals("habr.com")||topic.equals("ai")||topic.equals("tech")||topic.equals("games")){String hub=topic.equals("ai")?"artificial_intelligence":topic.equals("games")?"gamedev":topic.equals("space")?"popular_science":topic.equals("science")?"popular_science":"";return "https://habr.com/ru/rss/"+(hub.isEmpty()?"articles/":"hubs/"+hub+"/articles/")+"?fl=ru";}
        if(topic.equals("all"))return "https://www.interfax.ru/rss";return newsFeed(topic,region,"lenta.ru");
    }
    static boolean topicMatch(JSONObject item,String topic){if(topic.equals("all"))return true;String content=(item.optString("title")+" "+item.optString("summary")+" "+item.optString("categories")).toLowerCase(java.util.Locale.ROOT);String[] words;switch(topic){case "ai":words=new String[]{"искусствен","нейросет","machine learning","artificial intelligence","chatgpt","openai","deepseek","llm","gpt"};break;case "sport":words=new String[]{"спорт","футбол","хоккей","теннис","олимпи","чемпион","sport","football","tennis"};break;case "economy":words=new String[]{"эконом","финанс","банк","бирж","инфляц","рынок","business","econom","finance"};break;case "space":words=new String[]{"космо","астро","ракет","орбит","spacex","space","nasa"};break;case "games":words=new String[]{"игр","гейм","steam","playstation","xbox","nintendo","game"};break;case "science":words=new String[]{"наук","учён","учен","исследован","биолог","физик","science","research"};break;default:words=new String[]{"техно","наука и техника","компьют","гаджет","цифров","программ","смартфон","интернет","technology","software"};}for(String word:words)if(content.contains(word))return true;return false;}
    static JSONArray newsSelection(String topic,String region,String domain)throws Exception{java.util.LinkedHashSet<String> feeds=new java.util.LinkedHashSet<>();feeds.add(newsFeed(topic,region,domain));if(domain.isEmpty()&&region.equals("ru")){feeds.add(newsFeed(topic,region,"lenta.ru"));if(topic.equals("all"))feeds.add(newsFeed(topic,region,"rbc.ru"));else if(!topic.equals("sport")&&!topic.equals("economy"))feeds.add(newsFeed(topic,region,"habr.com"));}Exception last=null;for(String feed:feeds){try{JSONArray all=parseNews(get(feed),new URL(feed).getHost()),selected=new JSONArray();boolean specific=feed.contains("/hubs/")&&!topic.equals("space")||feed.contains("/sport/")||feed.contains("/economics/")||feed.contains("science_and_environment")&&!topic.equals("space")||feed.contains("/news/business/");for(int n=0;n<all.length();n++)if(specific||topicMatch(all.getJSONObject(n),topic))selected.put(all.getJSONObject(n));if(selected.length()>0)return selected;last=new IOException("В выбранном источнике сейчас нет публикаций этой темы");}catch(Exception e){last=e;}}throw last==null?new IOException("Лента недоступна"):last;}
    static JSONObject forecast(String city)throws Exception{if(city.isEmpty()||city.length()>100)throw new IOException("Введите город до 100 символов");String encoded=URLEncoder.encode(city,"UTF-8");JSONObject geo=new JSONObject(get("https://geocoding-api.open-meteo.com/v1/search?name="+encoded+"&count=1&language=ru&format=json"));JSONArray results=geo.optJSONArray("results");if(results==null||results.length()==0)throw new IOException("Город не найден. Уточните название");JSONObject place=results.getJSONObject(0);double lat=place.getDouble("latitude"),lon=place.getDouble("longitude");JSONObject forecast=new JSONObject(get("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_probability_max,weather_code&wind_speed_unit=ms&timezone=auto&forecast_days=7"));return weatherData(place,forecast);}
    static JSONObject weatherData(JSONObject place,JSONObject forecast)throws Exception{JSONObject daily=forecast.getJSONObject("daily");JSONArray dates=daily.getJSONArray("time"),max=daily.getJSONArray("temperature_2m_max"),min=daily.getJSONArray("temperature_2m_min"),rain=daily.getJSONArray("precipitation_probability_max"),codes=daily.getJSONArray("weather_code"),days=new JSONArray();if(dates.length()!=7||max.length()!=7||min.length()!=7||rain.length()!=7||codes.length()!=7)throw new IOException("Источник вернул неполный прогноз; прежний кэш сохранён");for(int n=0;n<7;n++)days.put(new JSONObject().put("date",dates.get(n)).put("max",max.get(n)).put("min",min.get(n)).put("rain",rain.get(n)).put("code",codes.get(n)));return new JSONObject().put("place",place.optString("name")).put("country",place.optString("country")).put("timezone",forecast.optString("timezone","UTC")).put("current",forecast.optJSONObject("current")==null?new JSONObject():forecast.getJSONObject("current")).put("days",days).put("updatedAt",MobileStore.now());}
    static String conditions(int code){if(code==0)return "Ясно";if(code==1)return "Преимущественно ясно";if(code==2)return "Переменная облачность";if(code==3)return "Пасмурно";if(code==45||code==48)return "Туман";if(code>=51&&code<=57)return "Морось";if(code>=61&&code<=67)return "Дождь";if(code>=71&&code<=77)return "Снег";if(code>=80&&code<=82)return "Ливень";if(code==85||code==86)return "Снегопад";if(code>=95&&code<=99)return "Гроза";return "Условия уточняются";}
    static String weather(String city)throws Exception{return forecast(city).toString();}
}
